function occupiedSquarePalette(){return occupiedSquarePalettes[$('occupied-square-colors').value]||null;}
function tintOccupiedSquare(context,piece,x,y,size,palette){if(!piece||!palette)return;context.fillStyle=piece>0?palette.white:palette.black;context.globalAlpha=.85;context.fillRect(x,y,size,size);context.globalAlpha=1;}
function updateOccupiedSquareColors(){const palette=occupiedSquarePalette();$('occupied-color-legend').hidden=!palette;if(palette){$('white-square-swatch').style.background=palette.white;$('black-square-swatch').style.background=palette.black;}requestRender();if(setupPreviewPosition)drawPreview(setupPreviewPosition);announce(palette?$('occupied-square-colors').selectedOptions[0].textContent+' occupied squares.':'Occupied-square coloring off.');}

function esc(value){return String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function number(value, fallback=0){const v=Number(value);return Number.isFinite(v)?v:fallback;}
function count(value){return new Intl.NumberFormat('en',{maximumFractionDigits:0}).format(number(value));}
function announce(message){$('announcer').textContent=message;}
function error(message){$('error-text').textContent=message;$('error-banner').hidden=false;}
function clearError(){$('error-banner').hidden=true;}
async function api(path,method='GET',data){
  const options={method,headers:{'Accept':'application/json'}};
  if(data!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}
  const response=await fetch(API+path,options);
  if(!response.ok){let detail;try{const body=await response.json();detail=body.detail||body.error||body.message;}catch{}throw new Error(typeof detail==='string'?detail:response.status===409?'The position changed. Please try again.':`Request failed (${response.status}).`);}
  return response.status===204?{}:response.json();
}
async function safely(action){try{clearError();return await action();}catch(e){error(e.message||String(e));console.error(e);return null;}}
function colorName(color){return color===1?'White':'Black';}
function playerFor(color){return state.game?.players?.[color===1?'white':'black'];}
function currentPosition(){if(state.replay!==null){return state.replay===0?state.initial:(state.moves[state.replay-1]?.position||state.game?.position);}return state.game?.position||state.preview;}
function fileName(col){let name='';for(let n=col+1;n>0;n=Math.floor((n-1)/26))name=String.fromCharCode(97+(n-1)%26)+name;return name;}
function squareName(index,size=currentPosition()?.size||24){return fileName(index%size)+(size-Math.floor(index/size));}
function moveText(move,size=currentPosition()?.size||24){if(!move)return '—';return `${squareName(move.from,size)} → ${squareName(move.to,size)}${move.promotion?' = '+pieceLetters[move.promotion]:''}`;}
