function fillConfig(config){$('setup-n').value=String(config.n||3);for(const r of document.querySelectorAll('input[name="setup"]'))r.checked=r.value===config.setup;$('setup-king').value=config.king_placement||'original';updateRangeOptions(config.slider_limit);$('setup-draw').value=config.no_progress_limit??'';}
function updateRangeOptions(selected){const old=selected===undefined?$('setup-range').value:selected,n=number($('setup-n').value,3);$('setup-range').innerHTML='<option value="">Unlimited</option>'+Array.from({length:n},(_,i)=>`<option value="${8*(i+1)}">${8*(i+1)} squares · ${i+1} board${i?'s':''}</option>`).join('');if(old!==null&&old!=='')$('setup-range').value=String(old);if($('setup-range').selectedIndex<0)$('setup-range').selectedIndex=0;}
function timeValue(color){const select=$(`setup-${color}-time`);return select.value==='custom'?Math.max(.1,number($(`setup-${color}-custom`).value,30)):number(select.value,2);}
function playerSelection(color){const value=$(`setup-${color}`).value;return {kind:value==='human'?'human':'ai',profile_id:value==='human'?null:value,seconds:timeValue(color),max_nodes:$(`setup-${color}-nodes`).value?number($(`setup-${color}-nodes`).value):null,max_depth:$(`setup-${color}-depth`).value?number($(`setup-${color}-depth`).value):null};}
function updateSetupMode(){const white=$('setup-white').value==='human',black=$('setup-black').value==='human';$('setup-mode-label').textContent=white&&black?'Two players — same keyboard':!white&&!black?'AI versus AI':'Human versus AI';for(const c of ['white','black']){$(`${c}-custom-field`).hidden=$(`setup-${c}-time`).value!=='custom';$(`setup-${c}-time`).disabled=$(`setup-${c}`).value==='human';}}

function svgFor(type,color){
  const fill=color===1?'#fff9e9':'#293f35',stroke=color===1?'#435b49':'#d2deca';
  const shapes={
    1:'<circle cx="24" cy="12" r="6"/><path d="M19 20h10l-2 6c0 4 2 7 5 10H16c3-3 5-6 5-10z"/><path d="M14 37h20v5H14z"/>',
    2:'<path d="M14 36c1-7 7-10 11-13l-7 1-5-4 6-9 3-6 4 4c9 2 12 10 10 16l-4 11z"/><path d="M21 15l-4 5 8-1M27 12l2 1" fill="none"/><circle cx="25.5" cy="14" r="1.1" fill="'+stroke+'" stroke="none"/><path d="M12 37h24v5H12z"/>',
    3:'<path d="M24 5c-4 5-10 9-10 15 0 5 4 8 10 8s10-3 10-8c0-6-6-10-10-15z"/><path d="M24 11l-5 10" fill="none"/><path d="M19 29h10l3 7H16zM12 38h24v4H12z"/>',
    4:'<path d="M12 7h6v6h4V7h4v6h4V7h6v13l-5 4 2 12H15l2-12-5-4z"/><path d="M15 19h18M17 24h14" fill="none"/><path d="M12 37h24v5H12z"/>',
    5:'<path d="M12 15l6 5 6-10 6 10 6-5-5 17H17z"/><circle cx="11" cy="12" r="2.5"/><circle cx="24" cy="7" r="2.5"/><circle cx="37" cy="12" r="2.5"/><path d="M16 33h16l2 4H14zM12 38h24v4H12z"/><path d="M18 27h12" fill="none"/>',
    6:'<path d="M22 4h4v5h5v4h-5v5h-4v-5h-5V9h5z"/><path d="M24 19c-8-7-13-1-12 5 1 3 4 5 6 8h12c2-3 5-5 6-8 1-6-4-12-12-5z"/><path d="M17 33h14l3 4H14zM12 38h24v4H12z"/><path d="M24 19v11" fill="none"/>'
  };
  return `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><g fill="${fill}" stroke="${stroke}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${shapes[type]}</g></svg>`;
}
function createPieceImages(){for(const color of [1,-1])for(let type=1;type<=6;type++){const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svgFor(type,color));image.onload=requestRender;pieceImages.set(color*type,image);}}
function resize(){const rect=$('board-viewport').getBoundingClientRect(),dpr=window.devicePixelRatio||1,oldW=camera.width,oldH=camera.height;camera.width=rect.width;camera.height=rect.height;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(camera.fitted||!oldW)fitBoard();else{camera.x+=(rect.width-oldW)/2;camera.y+=(rect.height-oldH)/2;requestRender();}}
function fitBoard(){const pos=currentPosition();if(!pos)return;camera.cell=Math.max(2,Math.min((camera.width-46)/pos.size,(camera.height-46)/pos.size));camera.x=(camera.width-camera.cell*pos.size)/2;camera.y=(camera.height-camera.cell*pos.size)/2;camera.fitted=true;requestRender();}
function zoomAt(factor,x=camera.width/2,y=camera.height/2){const old=camera.cell,next=Math.min(120,Math.max(2,old*factor));camera.x=x-(x-camera.x)*next/old;camera.y=y-(y-camera.y)*next/old;camera.cell=next;camera.fitted=false;$('follow-moves').checked=false;requestRender();}
function focusSquare(index,cell=40){const pos=currentPosition();if(!pos||index===null||index===undefined)return;const col=index%pos.size,row=Math.floor(index/pos.size),c=camera.flipped?pos.size-1-col:col,r=camera.flipped?pos.size-1-row:row;camera.cell=Math.max(camera.cell,cell);camera.x=camera.width/2-(c+.5)*camera.cell;camera.y=camera.height/2-(r+.5)*camera.cell;camera.fitted=false;requestRender();}
function kingSquare(color=currentPosition()?.turn||1){return currentPosition()?.board.indexOf(color*6)??null;}
function playView(){focusSquare(state.selected??state.focus??kingSquare(playerFor(1)?.kind==='human'?1:playerFor(-1)?.kind==='human'?-1:currentPosition()?.turn),40);}
function boardPoint(index,pos=currentPosition()){const col=index%pos.size,row=Math.floor(index/pos.size);return {x:camera.x+(camera.flipped?pos.size-1-col:col)*camera.cell,y:camera.y+(camera.flipped?pos.size-1-row:row)*camera.cell};}
function squareAt(x,y){const pos=currentPosition();if(!pos)return null;let col=Math.floor((x-camera.x)/camera.cell),row=Math.floor((y-camera.y)/camera.cell);if(col<0||row<0||col>=pos.size||row>=pos.size)return null;if(camera.flipped){col=pos.size-1-col;row=pos.size-1-row;}return row*pos.size+col;}
function requestRender(){if(renderPending)return;renderPending=true;requestAnimationFrame(()=>{renderPending=false;drawBoard();});}
function drawBoard(){
  const pos=currentPosition(),w=camera.width,h=camera.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#e6eadf';ctx.fillRect(0,0,w,h);if(!pos)return;
  const n=pos.size,s=camera.cell,palette=occupiedSquarePalette(),displayedCheck=state.replay===null?state.game?.check:positionStatisticsCache.get(statisticKey())?.in_check;const c0=Math.max(0,Math.floor(-camera.x/s)),c1=Math.min(n-1,Math.floor((w-camera.x)/s)),r0=Math.max(0,Math.floor(-camera.y/s)),r1=Math.min(n-1,Math.floor((h-camera.y)/s));
  const last=state.replay===0?null:state.replay!==null?state.moves[state.replay-1]?.move:state.moves.at(-1)?.move;
  for(let row=r0;row<=r1;row++)for(let col=c0;col<=c1;col++){
    const realRow=camera.flipped?n-1-row:row,realCol=camera.flipped?n-1-col:col,index=realRow*n+realCol,x=camera.x+col*s,y=camera.y+row*s;
    ctx.fillStyle=(realRow+realCol)%2?'#819a82':'#f0eadb';ctx.fillRect(Math.floor(x),Math.floor(y),Math.ceil(s)+.5,Math.ceil(s)+.5);
    tintOccupiedSquare(ctx,pos.board[index],Math.floor(x),Math.floor(y),Math.ceil(s)+.5,palette);
    if(last&&(index===last.from||index===last.to)){ctx.fillStyle='#dfc56a66';ctx.fillRect(x,y,s,s);}
    if(index===state.selected){ctx.fillStyle='#c6d572aa';ctx.fillRect(x,y,s,s);}
    if(displayedCheck&&pos.board[index]===pos.turn*6){ctx.fillStyle='#c46d5a99';ctx.fillRect(x,y,s,s);}
    const piece=pos.board[index];if(piece){if(s<8){ctx.fillStyle=piece>0?'#fff8e6':'#213c2f';const inset=palette?0.25:0.1;ctx.fillRect(x+s*inset,y+s*inset,s*(1-2*inset),s*(1-2*inset));if(Math.abs(piece)===6){ctx.strokeStyle='#d9b65d';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x+s/2,y+s/2,Math.max(2.5,s*.65),0,Math.PI*2);ctx.stroke();}}else{const image=pieceImages.get(piece);if(image?.complete&&image.naturalWidth)ctx.drawImage(image,x+s*.07,y+s*.07,s*.86,s*.86);else{ctx.fillStyle=piece>0?'#fff7e4':'#233f31';ctx.font=`${s*.85}px Georgia`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(['','♟','♞','♝','♜','♛','♚'][Math.abs(piece)],x+s/2,y+s*.52);}}}
    if(palette&&s>=8&&(index===state.selected||(displayedCheck&&piece===pos.turn*6))){ctx.strokeStyle=index===state.selected?'#284e35':'#8d2632';ctx.lineWidth=Math.max(2,s*.07);ctx.strokeRect(x+ctx.lineWidth/2,y+ctx.lineWidth/2,s-ctx.lineWidth,s-ctx.lineWidth);}
  }
  if($('guides').checked){ctx.strokeStyle='#364d3b55';ctx.lineWidth=1;ctx.beginPath();for(let k=8;k<n;k+=8){let p=camera.x+k*s;ctx.moveTo(p,camera.y);ctx.lineTo(p,camera.y+n*s);p=camera.y+k*s;ctx.moveTo(camera.x,p);ctx.lineTo(camera.x+n*s,p);}ctx.stroke();}
  const seen=new Set();for(const move of state.legal){if(seen.has(move.to))continue;seen.add(move.to);const p=boardPoint(move.to,pos);ctx.beginPath();if(pos.board[move.to]){ctx.strokeStyle='#1e553ab0';ctx.lineWidth=Math.max(2,s*.075);ctx.arc(p.x+s/2,p.y+s/2,s*.42,0,Math.PI*2);ctx.stroke();}else{ctx.fillStyle='#285f4060';ctx.arc(p.x+s/2,p.y+s/2,Math.max(2,s*.115),0,Math.PI*2);ctx.fill();}}
  if(state.focus!==null&&document.activeElement===canvas){const p=boardPoint(state.focus,pos);ctx.strokeStyle='#f8fcbd';ctx.lineWidth=2;ctx.strokeRect(p.x+2,p.y+2,s-4,s-4);}
  ctx.strokeStyle='#62785a55';ctx.lineWidth=1;ctx.strokeRect(camera.x-.5,camera.y-.5,n*s+1,n*s+1);
  ctx.font='9px Inter, system-ui, sans-serif';ctx.fillStyle='#61755b';ctx.textAlign='center';ctx.textBaseline='middle';const labelStep=Math.max(1,Math.ceil(22/s));
  for(let c=c0;c<=c1;c++){if(c%labelStep!==0)continue;const real=camera.flipped?n-1-c:c;ctx.fillText(fileName(real),camera.x+(c+.5)*s,Math.max(10,Math.min(h-10,camera.y+n*s+12)));}
  for(let r=r0;r<=r1;r++){if(r%labelStep!==0)continue;const real=camera.flipped?n-1-r:r;ctx.fillText(String(n-real),Math.max(12,Math.min(w-12,camera.x-13)),camera.y+(r+.5)*s);}
  $('zoom-label').textContent=camera.fitted?'Fit':Math.round(s/40*100)+'%';$('overview-hint').hidden=s>=14;$('minimap').hidden=camera.fitted||n*s<=Math.min(w,h);drawMinimap(pos);
}
function drawMinimap(pos){if(mini.hidden)return;const z=mini.width/pos.size,n=pos.size,palette=occupiedSquarePalette();mctx.clearRect(0,0,mini.width,mini.height);for(let r=0;r<n;r++)for(let c=0;c<n;c++){const rr=camera.flipped?n-1-r:r,cc=camera.flipped?n-1-c:c,piece=pos.board[rr*n+cc];mctx.fillStyle=(r+c)%2?'#819a82':'#f0eadb';mctx.fillRect(c*z,r*z,z+.5,z+.5);tintOccupiedSquare(mctx,piece,c*z,r*z,z+.5,palette);if(piece){mctx.fillStyle=piece>0?'#fff8e7':'#223e30';const inset=palette?0.3:0.19;mctx.fillRect(c*z+z*inset,r*z+z*inset,Math.max(palette?0.5:1,z*(1-2*inset)),Math.max(palette?0.5:1,z*(1-2*inset)));}}mctx.fillStyle='#fffa9c18';mctx.strokeStyle='#e6c966';mctx.lineWidth=2;const x=-camera.x/camera.cell*z,y=-camera.y/camera.cell*z,w=camera.width/camera.cell*z,h=camera.height/camera.cell*z;mctx.fillRect(x,y,w,h);mctx.strokeRect(x,y,w,h);}
function drawPreview(position){setupPreviewPosition=position;const pc=$('preview-board'),pctx=pc.getContext('2d'),size=position.size,s=pc.width/size,palette=occupiedSquarePalette();pctx.clearRect(0,0,pc.width,pc.height);for(let r=0;r<size;r++)for(let c=0;c<size;c++){const v=position.board[r*size+c];pctx.fillStyle=(r+c)%2?'#819a82':'#f0eadb';pctx.fillRect(c*s,r*s,s+.5,s+.5);tintOccupiedSquare(pctx,v,c*s,r*s,s+.5,palette);if(v){if(s>=9&&pieceImages.get(v)?.complete)pctx.drawImage(pieceImages.get(v),c*s,r*s,s,s);else{pctx.fillStyle=v>0?'#fff8e7':'#233f31';pctx.beginPath();pctx.arc((c+.5)*s,(r+.5)*s,Math.max(.6,s*.3),0,Math.PI*2);pctx.fill();}}}}

async function updatePreview(){const request=++state.previewRequest,config=currentConfig(),n=config.n;$('preview-dimensions').textContent=`${8*n} × ${8*n} SQUARES`;$('preview-pieces').textContent=`${count(config.setup==='blocks'?15*n*n+1:15*n+1)} pieces per side`;try{const result=await api('/preview','POST',{config});if(request!==state.previewRequest)return;const pos=result.position||result;drawPreview(pos);if(!state.game){state.preview=pos;fitBoard();}}catch(e){if(!state.game)error(e.message);}}
function openSetup(){if(state.game){fillConfig(state.game.config);for(const side of ['white','black']){const player=state.game.players[side];$(`setup-${side}`).value=player.kind==='human'?'human':player.profile?.id||player.profile_id||'balanced';const seconds=number(player.seconds,2),preset=[2,5,10,30,60].includes(seconds);$(`setup-${side}-time`).value=preset?String(seconds):'custom';$(`setup-${side}-custom`).value=seconds;$(`setup-${side}-nodes`).value=player.max_nodes??'';$(`setup-${side}-depth`).value=player.max_depth??'';}$('setup-learning').checked=state.game.learning!==false;}updateRangeOptions(state.game?.config?.slider_limit);updateSetupMode();updatePreview();$('new-game-dialog').showModal();}
function populateProfiles(){
  const options=state.profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');for(const id of ['setup-white','setup-black','profile-select','batch-white','batch-black']){const select=$(id),old=select.value;select.innerHTML=(id.startsWith('setup-')?'<option value="human">Human · same device</option>':'')+options;if([...select.options].some(o=>o.value===old))select.value=old;}
  if(!$('setup-black').dataset.initialized){$('setup-white').value='human';$('setup-black').value=state.profiles.find(p=>p.id==='balanced')?.id||state.profiles[0]?.id||'human';$('setup-black').dataset.initialized='true';$('batch-white').value=state.profiles[0]?.id||'';$('batch-black').value=state.profiles[1]?.id||state.profiles[0]?.id||'';}
  updateSetupMode();fillProfileEditor();
}
async function createGame(){
  const button=$('start-game');button.disabled=true;
  try{const result=await api('/games','POST',{config:currentConfig(),players:{white:playerSelection('white'),black:playerSelection('black')},learning:$('setup-learning').checked,view_delay:number($('view-delay').value,.5)});await setGame(result.game||result,[],true);$('new-game-dialog').close();activateTab('play');announce('New game started. '+$('turn-text').textContent);}
  finally{button.disabled=false;}
}
async function loadGame(id){const result=await api(`/games/${id}`);await setGame(result.game||result,result.moves||[],true);activateTab('play');}
async function setGame(game,moves=[],reset=false){
  const changed=state.game?.id!==game.id;if(changed||reset){replayPlayback.stop();state.moves=moves;state.selected=null;state.legal=[];state.focus=null;state.replay=null;state.search=null;state.events=[];state.eventKeys.clear();state.lastSearchKey=null;state.lastSearchDepth=0;state.initial=null;state.evaluationRevision=null;state.lastSearchError=null;}
  state.game=game;state.lastRevision=game.revision??0;
  if(changed||reset){capturesHistory=[];fillConfig(game.config);state.initial=game.initial_position;if(!state.initial){const result=await api('/preview','POST',{config:game.config});state.initial=result.position||result;}fitBoard();}
  mergeMoves(moves);if(changed||reset){const saved=state.moves.findLast(m=>m.stats&&m.stats.nodes!==undefined);if(saved){const color=-(saved.position?.turn||1),profile=playerFor(color)?.profile;receiveSearch({...saved.stats,thinking:false,reason:saved.stats.reason||'saved summary',profile_name:saved.stats.profile_name||profile?.name});}}renderGame();requestRender();
}
function mergeMoves(moves){if(!Array.isArray(moves)||!moves.length)return;const byRevision=new Map(state.moves.map((m,i)=>[m.revision??i+1,m]));for(const [i,m] of moves.entries())byRevision.set(m.revision??i+1,m);state.moves=[...byRevision.values()].sort((a,b)=>(a.revision??0)-(b.revision??0));}
function gameFinished(game=state.game){return !!game&&game.status!=='playing';}
function isHumanTurn(){return !!state.game&&!gameFinished()&&state.replay===null&&playerFor(state.game.position.turn)?.kind==='human';}
function renderPlayer(color){const player=playerFor(color),target=$(color===1?'white-player':'black-player');if(!player){target.innerHTML='';return;}const profile=player.profile||{},human=player.kind==='human',current=state.game.position.turn===color&&!gameFinished();target.classList.toggle('current',current);target.innerHTML=`<div class="player-avatar ${color===1?'white':''}">${color===1?'♔':'♚'}</div><div><div class="player-name">${esc(human?'Human':profile.name||player.profile_id||'AI player')}</div><div class="player-detail">${colorName(color)}${human?' · Your move, your ideas':` · v${esc(profile.version||1)} · ${number(player.seconds,2)}s max`}</div></div><span class="player-indicator"></span>`;}
function renderGame(){const game=state.game;if(!game)return;if(game.search_error&&state.lastSearchError!==game.search_error){error(`AI search paused: ${game.search_error}`);state.lastSearchError=game.search_error;}else if(!game.search_error){state.lastSearchError=null;}const pos=currentPosition()||game.position,n=game.config.n,mode=game.players.white.kind==='human'&&game.players.black.kind==='human'?'Two players · same keyboard':game.players.white.kind==='ai'&&game.players.black.kind==='ai'?'AI versus AI':'Human versus AI';$('game-mode').textContent=mode.toUpperCase();$('game-title').textContent=`${pos.size} × ${pos.size}. A bigger game.`;$('game-config-label').textContent=`N = ${n} · ${game.config.setup==='blocks'?'BLOCK EXPANSION':'REPEATED ROWS'} · ${game.config.slider_limit?game.config.slider_limit+'-SQUARE RANGE':'UNLIMITED RANGE'}`;
  let turnText=state.replay!==null?'Replaying position '+state.replay:gameFinished()?game.status==='checkmate'?`${colorName(game.winner)} wins · checkmate`:game.status==='resigned'?`${colorName(game.winner)} wins`:`${game.status==='draw'?'Draw':game.status==='cutoff'?'Ply limit reached':'Game ended'}`:`${colorName(game.position.turn)} to move${game.check?' · check':''}${game.paused?' · paused':''}`;
  $('turn-text').textContent=turnText;$('turn-pill').classList.toggle('black',pos.turn===-1);$('turn-pill').classList.toggle('finished',gameFinished());renderPlayer(-1);renderPlayer(1);
  $('mode-note').textContent=game.search_error?`Search paused: ${game.search_error}`:gameFinished()?game.reason?String(game.reason).replaceAll('_',' '):'This game is saved in your library.':mode.startsWith('Two players')?'Take turns at the same keyboard. The board stays facing the same way until you flip it.':mode==='AI versus AI'?'Two minds, one very big board. Pause, step, or open the search room to follow their thinking.':'Select one of your pieces, then choose a highlighted square. Your AI opponent will take the next turn.';
  const hasAI=game.players.white.kind==='ai'||game.players.black.kind==='ai';$('pause-game').disabled=!hasAI||gameFinished();$('pause-game').textContent=game.paused?'▶ Resume':'Ⅱ Pause';$('step-game').disabled=!hasAI||gameFinished()||!game.paused;$('move-now').disabled=gameFinished()||playerFor(game.position.turn)?.kind!=='ai'||game.paused;$('resign-game').disabled=gameFinished()||playerFor(game.position.turn)?.kind!=='human';$('draw-game').disabled=gameFinished();$('export-game').href=`${API}/games/${game.id}/export`;$('move-count').textContent=`${Math.ceil(state.moves.length/2)} move${state.moves.length>2||state.moves.length===0?'s':''}`;
  renderMoves();renderBoardStatistics();renderSearch();if($('evaluation-panel').open&&state.evaluationRevision!==`${game.id}:${game.revision}`)safely(refreshEvaluation);
}

function materialText(value){return new Intl.NumberFormat('en',{maximumFractionDigits:1}).format(Math.abs(value)<.0001?0:value);}
function statisticKey(){return state.game?`${state.game.id}:${state.replay===null?'live:'+state.game.revision:'replay:'+state.replay}`:'';}
function pieceGroupMarkup(counts,color,captured=false){const types=captured?[5,4,3,2,1]:[6,5,4,3,2,1];return types.filter(kind=>!captured||counts[kind]).map(kind=>{const label=`${count(counts[kind])} ${colorName(color)} ${pieceNames[kind]}${counts[kind]===1?'':'s'}`;return `<span class="${captured?'captured-piece':'piece-count'}" title="${esc(label)}" aria-label="${esc(label)}"><img class="piece-symbol" src="${pieceImages.get(color*kind)?.src||''}" alt="" aria-hidden="true"><span>${count(counts[kind])}</span></span>`;}).join('');}
function renderBoardStatistics(){
  const pos=currentPosition();if(!state.game||!pos||!state.initial)return;
  const armies=countArmies(pos.board),ordered=camera.flipped?[-1,1]:[1,-1];
  $('army-stats').innerHTML=ordered.map(color=>{const army=armies[color===1?'white':'black'];return `<article class="army-stat-card ${color===1?'white':'black'}"><div class="army-stat-heading"><span class="side-label">${colorName(color)}</span><strong class="piece-total">${count(army.total)} pieces</strong></div><div class="piece-counts">${pieceGroupMarkup(army.counts,color)}</div><div class="army-stat-detail">${materialText(army.material)} material · remaining on board</div></article>`;}).join('');
  capturesHistory=captureTimeline(state.initial,state.moves,capturesHistory);
  const captured=capturesHistory[state.replay===null?state.moves.length:state.replay]||capturesHistory[0];
  for(const [index,color] of ordered.entries()){
    const side=color===1?'white':'black',groups=captured[side],total=groups.reduce((a,b)=>a+b,0),tray=$(index===0?'captures-left':'captures-right');
    tray.setAttribute('aria-label',`Pieces captured by ${colorName(color)}`);
    tray.innerHTML=`<div class="capture-heading"><span>${colorName(color)}</span><strong>${count(total)}</strong></div><div class="capture-subtitle">Captured</div><div class="captured-groups">${pieceGroupMarkup(groups,-color,true)}</div>${total?'':'<div class="capture-empty">None yet</div>'}<div class="army-stat-detail" title="Material value of the pieces captured by ${colorName(color)}">${materialText(materialValue(groups))} material</div>`;
  }
  const stats=positionStatisticsCache.get(statisticKey()),balance=armies.white.material-armies.black.material,occupied=armies.white.total+armies.black.total,captures=[...captured.white,...captured.black].reduce((a,b)=>a+b,0);
  const materialEdge=Math.abs(balance)<.0001?'Even':`${balance>0?'White':'Black'} +${materialText(Math.abs(balance))}`;
  const chips=[
    {label:`${colorName(pos.turn)} legal moves`,value:stats?count(stats.legal_moves):'…',title:'All legal moves for the player to move; promotion choices count separately.'},
    {label:'Captures available',value:stats?count(stats.legal_captures):'…',title:`Legal capturing moves available to ${colorName(pos.turn)}, including en passant.`},
    {label:state.replay===null?'Current move':'Replay move',value:count(Math.floor(pos.ply/2)+1),title:`${count(pos.ply)} plies played`},
    {label:'Material edge',value:materialEdge,title:'Material values: pawn 1, knight 3.2, bishop 3.3, rook 5, queen 9; kings excluded.'},
    {label:'Pieces captured',value:count(captures),title:'Actual captures since the saved starting position; promotions are tracked separately.'},
    {label:'Board occupied',value:`${(occupied/(pos.size*pos.size)*100).toFixed(1)}%`,title:`${count(occupied)} occupied · ${count(pos.size*pos.size-occupied)} empty squares`}
  ];
  $('position-stats').innerHTML=chips.map(chip=>`<div class="position-stat" title="${esc(chip.title)}"><span>${esc(chip.label)}</span><strong>${esc(chip.value)}</strong></div>`).join('');
  if(!stats&&!positionStatisticsPending.has(statisticKey())&&Date.now()>=statisticsRetryAt)void refreshPositionStatistics();
}
async function refreshPositionStatistics(){
  const key=statisticKey(),id=state.game.id,revision=state.game.revision,index=state.replay;positionStatisticsPending.add(key);
  try{const query=new URLSearchParams({revision:String(revision)});if(index!==null)query.set('position_index',String(index));const result=await api(`/games/${id}/statistics?${query}`);positionStatisticsCache.set(key,result);if(positionStatisticsCache.size>128)positionStatisticsCache.delete(positionStatisticsCache.keys().next().value);if(statisticKey()===key){renderBoardStatistics();requestRender();}}
  catch{statisticsRetryAt=Date.now()+1000;}
  finally{positionStatisticsPending.delete(key);}
}
function renderMoves(){const list=$('move-list');if(!state.moves.length){list.innerHTML='<div class="empty-state"><span>↗</span>Your first move starts the story.</div>';}else{const rows=[];for(let i=0;i<state.moves.length;i+=2){const make=(m,j)=>m?`<button class="move-entry ${state.replay===j+1?'selected':''}" data-replay="${j+1}">${esc(moveText(m.move,state.game.position.size))}</button>`:'<span></span>';rows.push(`<div class="move-row"><span class="move-number">${Math.floor(i/2)+1}.</span>${make(state.moves[i],i)}${make(state.moves[i+1],i+1)}</div>`);}const oldScroll=list.scrollTop,atEnd=list.scrollHeight-oldScroll-list.clientHeight<35;list.innerHTML=rows.join('');if(atEnd&&state.replay===null)list.scrollTop=list.scrollHeight;else list.scrollTop=oldScroll;}
  $('replay-label').textContent=state.replay===null?'Live game':`Position ${state.replay} / ${state.moves.length}`;$('replay-start').disabled=!state.moves.length;$('replay-prev').disabled=state.replay===0||!state.moves.length;$('replay-next').disabled=state.replay===null||state.replay>=state.moves.length;$('replay-live').disabled=state.replay===null;renderTimeline();
}
function renderTimeline(){const total=state.moves.length,frame=state.replay===null?total:state.replay,slider=$('game-timeline-slider');slider.max=String(total);slider.value=String(frame);slider.disabled=!total;const positionText=state.replay===null?`Live · ${count(total)} step${total===1?'':'s'}`:frame===0?`Start · 0 / ${count(total)}`:`Step ${count(frame)} / ${count(total)} · ${moveText(state.moves[frame-1]?.move)}`;$('timeline-position').textContent=positionText;slider.setAttribute('aria-valuetext',positionText);$('timeline-play').disabled=!total;$('timeline-play').textContent=replayPlayback.playing?'■ Stop':'▶ Play';$('timeline-play').setAttribute('aria-label',replayPlayback.playing?'Stop replay':'Play replay');$('timeline-play').setAttribute('aria-pressed',String(replayPlayback.playing));$('timeline-live').disabled=state.replay===null;$('timeline-note').textContent=!total?'No steps recorded yet.':replayPlayback.playing?(gameFinished()?'Looping · 1 step / sec · completed game':'Looping · 1 step / sec · live game continues'):state.replay===null?'Slide to review earlier steps.':(gameFinished()?'Viewing history · completed game':'Viewing history · live game continues');}
function setReplay(index,fromPlayback=false){if(!fromPlayback)replayPlayback.stop();state.selected=null;state.legal=[];state.focus=null;state.legalRequest++;state.replay=index===null?null:Math.min(state.moves.length,Math.max(0,index));$('board-description').textContent=state.replay===null?'Select a piece to see its legal moves.':'Reviewing recorded steps. Choose Live to return to play.';renderGame();requestRender();}
async function selectSquare(index){
  const pos=currentPosition();if(!pos||index===null)return;state.focus=index;
  if(camera.cell<14){focusSquare(index,40);return;}
  if(state.replay!==null){$('board-description').textContent=`${squareName(index)} · replay mode. Return to the live game to play.`;requestRender();return;}
  if(!isHumanTurn()){const piece=pos.board[index];$('board-description').textContent=piece?`${colorName(Math.sign(piece))} ${pieceNames[Math.abs(piece)]} on ${squareName(index)}. ${gameFinished()?'This game has ended.':'The AI is thinking.'}`:'Watch the AI or explore the board while it thinks.';requestRender();return;}
  const candidates=state.legal.filter(m=>m.to===index);if(candidates.length){let move=candidates[0];if(candidates.some(m=>m.promotion)){const choice=await choosePromotion(candidates,pos.turn);if(!choice)return;move=choice;}await playMove(move);return;}
  if(pos.board[index]*pos.turn>0){state.selected=index;state.legal=[];const request=++state.legalRequest,revision=state.game.revision;requestRender();const result=await api(`/games/${state.game.id}/legal?from_square=${index}`);if(request!==state.legalRequest||revision!==state.game.revision)return;state.legal=result.moves||[];$('board-description').textContent=`${colorName(pos.turn)} ${pieceNames[Math.abs(pos.board[index])]} · ${squareName(index)} · ${new Set(state.legal.map(m=>m.to)).size} legal destinations`;announce($('board-description').textContent);}
  else{state.selected=null;state.legal=[];$('board-description').textContent='Select a piece to see its legal moves.';}requestRender();
}
async function playMove(move){const id=state.game.id,revision=state.game.revision;state.selected=null;state.legal=[];state.legalRequest++;const result=await api(`/games/${id}/move`,'POST',{move,revision});state.game=result.game||result;$('board-description').textContent='Select a piece to see its legal moves.';renderGame();requestRender();await pollGame(true);announce(moveText(move)+'. '+$('turn-text').textContent);}
function choosePromotion(moves,color){const dialog=$('promotion-dialog'),options=$('promotion-options');return new Promise(resolve=>{options.innerHTML=moves.map(m=>`<button type="button" data-piece="${m.promotion}"><img alt="" src="${pieceImages.get(color*m.promotion)?.src||''}">${pieceNames[m.promotion]}</button>`).join('');const cleanup=()=>{options.onclick=null;dialog.oncancel=null;};options.onclick=e=>{const button=e.target.closest('[data-piece]');if(!button)return;const result=moves.find(m=>m.promotion===number(button.dataset.piece));dialog.close();cleanup();resolve(result);};dialog.oncancel=()=>{cleanup();resolve(null);};dialog.showModal();});}

function appendSearchEvent(message,time){if(!message)return;const previous=state.events.at(-1),key=`${time??''}|${message}`;if(previous?.message===message||state.eventKeys.has(key))return;state.eventKeys.add(key);state.events.push({message,time:time??new Date().toLocaleTimeString('en-GB')});if(state.events.length>200)state.events.splice(0,state.events.length-200);}
function receiveSearch(search){if(!search)return;const key=search.search_id||search.id||`${state.game?.id}:${search.ply??state.game?.position?.ply}:${search.profile_version??''}`;if(key!==state.lastSearchKey){state.lastSearchKey=key;state.lastSearchDepth=0;state.events=[];state.eventKeys.clear();appendSearchEvent(`Search started · ${number(search.seconds,number(playerFor(state.game.position.turn)?.seconds,2))}s maximum`);}
  state.search=search;state.searchReceived=performance.now();if(Array.isArray(search.events)){for(const event of search.events)appendSearchEvent(typeof event==='string'?event:event.message||event.event,event.time);}
  const completed=number(search.completed_depth);if(completed>state.lastSearchDepth){if(!search.events?.length)appendSearchEvent(`Depth ${completed} completed · ${count(search.nodes)} positions · ${search.selective?'selective':'full-width'} search`);state.lastSearchDepth=completed;}
  if(search.reason&&search.reason!=='searching'&&!search.events?.length)appendSearchEvent(`${String(search.reason).replaceAll('_',' ')} · completed depth ${completed}${search.move?' · '+moveText(search.move):''}`);
  renderSearch();
}
function isSearching(){if(!state.game||!state.search)return false;return state.search.thinking!==false&&state.search.active!==false&&state.search.running!==false&&(!state.search.reason||state.search.reason==='searching')&&!gameFinished()&&!state.game.paused&&playerFor(state.game.position.turn)?.kind==='ai';}
function renderSearchClock(){const search=state.search;if(!search)return;const active=isSearching(),elapsed=number(search.elapsed)+(active?(performance.now()-state.searchReceived)/1000:0),budget=number(search.seconds||search.budget||search.limit_seconds,number(playerFor(state.game?.position.turn)?.seconds,2)),remaining=active?Math.max(0,number(search.remaining,budget-number(search.elapsed))-(performance.now()-state.searchReceived)/1000):Math.max(0,number(search.remaining,budget-elapsed));$('search-clock').textContent=`${elapsed.toFixed(1)}s elapsed · ${remaining.toFixed(1)}s left`;$('search-progress').value=Math.min(1,elapsed/Math.max(.1,budget));}
function renderSearch(){const search=state.search,thinking=isSearching();$('search-indicator').classList.toggle('thinking',thinking);if(!search){$('search-summary').textContent='A window into the thinking.';$('search-ai').textContent='Waiting for a search';$('search-clock').textContent='—';$('search-progress').value=0;$('search-stats').innerHTML=['Positions','Depth completed','Branches cut','Cache hits'].map(label=>`<div><span>${label}</span><strong>—</strong></div>`).join('');$('search-pv').textContent='A legal move will appear here when the AI starts thinking.';$('search-log').innerHTML='<div class="log-empty">Search events, budgets, and completed depths appear here.</div>';return;}$('search-summary').textContent=thinking?`${count(search.nodes)} positions · depth ${number(search.completed_depth)} complete`:`${count(search.nodes)} positions · ${search.reason?String(search.reason).replaceAll('_',' '):'search paused'}`;const profile=search.profile_name||search.ai_name||playerFor(state.game?.position.turn)?.profile?.name||'AI';$('search-ai').textContent=`${profile} · ${search.selective?'selective':'full-width'} search`;
  const rootTotal=search.root_total??search.candidates,stats=[['Positions',count(search.nodes)],['Evaluations',count(search.evaluated)],['Moves generated',count(search.generated)],['Depth completed',`${number(search.completed_depth)}${search.depth>search.completed_depth?' / '+search.depth+(thinking?' now':' partial'):''}`],['Branches cut',count(search.cutoffs)],['Cache hits',count(search.tt_hits)],['Root moves',`${count(search.root_done)}${rootTotal!==undefined?' / '+count(rootTotal):''}`],['Quiescence nodes',count(search.qnodes)],['Positions / sec',count(number(search.nodes)/Math.max(.001,number(search.elapsed)))],['Eval · AI view',Number.isFinite(search.score)?`${search.score>=0?'+':''}${Number(search.score).toFixed(2)}`:'—']];$('search-stats').innerHTML=stats.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('');$('search-pv').textContent=(search.pv?.length?search.pv:search.move?[search.move]:[]).slice(0,8).map(m=>moveText(m)).join('  ·  ')||'Finding a legal starting move…';
  const log=$('search-log'),atEnd=log.scrollHeight-log.scrollTop-log.clientHeight<30;log.innerHTML=state.events.map(e=>`<div><time>${esc(typeof e.time==='number'?e.time.toFixed(1)+'s':e.time)}</time>${esc(e.message)}</div>`).join('')||'<div class="log-empty">Search in progress…</div>';if(atEnd)log.scrollTop=log.scrollHeight;renderSearchClock();
}
async function pollGame(force=false){if(!state.game||state.polling&&!force)return;state.polling=true;const id=state.game.id;try{const result=await api(`/games/${id}/updates?revision=${state.lastRevision??0}`);if(state.game?.id!==id)return;const oldRevision=state.game.revision,oldPly=state.game.position.ply;if(result.game&&result.game.revision>=state.game.revision)state.game=result.game;state.lastRevision=Math.max(state.lastRevision,result.game?.revision??0);mergeMoves(result.moves||[]);if(result.search)receiveSearch(result.search);if(state.game.revision!==oldRevision||state.game.position.ply!==oldPly){state.selected=null;state.legal=[];state.legalRequest++;$('board-description').textContent=state.replay===null?'Select a piece to see its legal moves.':'Reviewing recorded steps. Choose Live to return to play.';if($('follow-moves').checked&&!camera.fitted&&state.replay===null){const last=state.moves.at(-1)?.move;if(last){const p=boardPoint(last.to),visible=p.x>=0&&p.y>=0&&p.x+camera.cell<=camera.width&&p.y+camera.cell<=camera.height;if(!visible)focusSquare(last.to,Math.max(camera.cell,24));}}renderGame();requestRender();}else{renderGame();} $('connection-status').textContent='Saved on your machine';}
  catch(e){$('connection-status').textContent='Reconnecting to your studio…';if(force)throw e;}finally{state.polling=false;}}
async function controlGame(action,extra={}){if(!state.game)return;const result=await api(`/games/${state.game.id}/control`,'POST',{action,...extra});if(result.game)state.game=result.game;renderGame();await pollGame(true);}
async function refreshEvaluation(){if(!state.game||!$('evaluation-panel').open)return;const id=state.game.id,revision=state.game.revision;state.evaluationRevision=`${id}:${revision}`;const result=await api(`/games/${id}/evaluation`);if(state.game?.id!==id)return;const sides=result.contributions||{},white=sides.white||{},black=sides.black||{},signed=v=>`${number(v)>=0?'+':''}${number(v).toFixed(3)}`;const aiSide=Object.keys(sides)[0];if(!aiSide){$('evaluation-values').innerHTML='<p class="small-muted">Choose an AI player to see its weighted evaluation.</p>';return;}const both=!!sides.white&&!!sides.black;$('evaluation-values').innerHTML=`<div class="evaluation-row header"><span>Feature</span><span>${both?'White AI':aiSide==='white'?'White AI':'Feature'}</span><span>${both?'Black AI':'AI value'}</span></div>`+Object.keys(featureNames).map(key=>`<div class="evaluation-row"><span>${featureNames[key]}</span><span>${signed(both?white[key]:result.features?.[key])}</span><span>${signed(both?black[key]:(sides[aiSide]||{})[key])}</span></div>`).join('')+`<div class="evaluation-row total"><span>Weighted total</span><span>${both?signed(Object.values(white).reduce((a,b)=>a+number(b),0)):''}</span><span>${signed(Object.values(both?black:sides[aiSide]).reduce((a,b)=>a+number(b),0))}</span></div>`;}
function activateTab(name){for(const button of document.querySelectorAll('.tab')){const active=button.dataset.tab===name;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));}for(const panel of document.querySelectorAll('.tab-panel'))panel.hidden=panel.id!==`tab-${name}`;if(name==='history')safely(refreshHistory);if(name==='training')safely(refreshBatches);}

function fillProfileEditor(override){const profile=override?.weights?override:state.profiles.find(p=>p.id===$('profile-select').value)||state.profiles[0];if(!profile)return;$('profile-name').value=profile.name;$('profile-version').textContent=`${override?.weights?'Inspecting version':'Base version'} ${profile.version||1} · ${profile.origin==='learning'?count(profile.games_learned)+' games learned':'matches keep their original settings'}`;$('weight-fields').innerHTML=Object.entries(featureNames).map(([key,label])=>`<label class="field">${label}<input type="number" step="0.01" data-weight="${key}" value="${number(profile.weights?.[key],fallbackWeights[key])}"></label>`).join('');$('profile-search').value=profile.search?.mode||'selective';$('profile-root-width').value=profile.search?.root_width||48;$('profile-width').value=profile.search?.width||16;$('profile-qdepth').value=profile.search?.qdepth??2;$('profile-qwidth').value=profile.search?.qwidth??8;$('profile-lambda').value=profile.learning?.lambda??.7;$('profile-exploration').value=profile.exploration||0;$('profile-learning').checked=profile.learning?.enabled!==false;$('profile-rate').value=profile.learning?.rate??.02;$('profile-feedback').textContent='';if(!override?.weights&&$('profile-versions-panel').open)safely(refreshProfileVersions);}
async function refreshProfileVersions(){const id=$('profile-select').value;if(!id)return;const result=await api(`/profiles/${id}/versions`);if($('profile-select').value!==id)return;state.profileVersions=result.versions||[];$('profile-versions-list').innerHTML=state.profileVersions.slice(0,30).map(profile=>`<button type="button" class="profile-version-item" data-version="${profile.version}"><span>v${profile.version} · ${esc(profile.origin||'saved')}</span><small>${profile.origin==='learning'?count(profile.games_learned)+' games learned · rules '+esc((profile.trained_rules||'').slice(0,7)):'Saved settings'} <b>Inspect ↗</b></small></button>`).join('');}
function editedProfile(){const source=state.profiles.find(p=>p.id===$('profile-select').value);if(!source)throw new Error('Choose an AI player first.');const profile=structuredClone(source);profile.name=$('profile-name').value.trim()||source.name;profile.weights={};for(const input of document.querySelectorAll('[data-weight]'))profile.weights[input.dataset.weight]=number(input.value);profile.search={...profile.search,mode:$('profile-search').value,root_width:number($('profile-root-width').value,48),width:number($('profile-width').value,16),qdepth:number($('profile-qdepth').value,2),qwidth:number($('profile-qwidth').value,8)};profile.exploration=number($('profile-exploration').value);profile.learning={...profile.learning,enabled:$('profile-learning').checked,rate:number($('profile-rate').value,.02),lambda:number($('profile-lambda').value,.7)};return profile;}
async function saveProfile(clone=false){const result=await api('/profiles','POST',{profile:editedProfile(),clone});const saved=result.profile||result;const fresh=await api('/profiles');state.profiles=fresh.profiles||fresh;populateProfiles();if(saved.id)$('profile-select').value=saved.id;fillProfileEditor();$('profile-feedback').textContent=clone?'New AI player created.':`Version ${saved.version||''} saved. New games will use these settings.`;}
async function resetProfile(){const id=$('profile-select').value;await api(`/profiles/${id}/reset`,'POST',{});const result=await api('/profiles');state.profiles=result.profiles||result;populateProfiles();$('profile-select').value=id;fillProfileEditor();$('profile-feedback').textContent='Starting personality restored in a new version.';}
async function startBatch(pilot=false){const payload={games:pilot?2:number($('batch-games').value,100),config:state.game?.config||currentConfig(),white_profile:$('batch-white').value,black_profile:$('batch-black').value,nodes:pilot?Math.min(500,number($('batch-nodes').value,500)):number($('batch-nodes').value,5000),max_plies:pilot?Math.min(100,number($('batch-plies').value,100)):number($('batch-plies').value,1000),workers:pilot?1:number($('batch-workers').value,2),learning:$('batch-learning').checked,seed:number($('batch-seed').value,1)};await api('/batches','POST',payload);await refreshBatches();announce(pilot?'Pilot batch queued.':'Training batch queued.');}
async function refreshBatches(){const result=await api('/batches');state.batches=result.batches||result;renderBatches();lastBatchRefresh=Date.now();}
function renderBatches(){
  const list=$('batch-list');if(!state.batches.length){list.innerHTML='<p class="muted">Your experiments will appear here.</p>';return;}
  list.innerHTML=state.batches.map(batch=>{
    const total=number(batch.games||batch.total_games||batch.total,100),completed=Array.isArray(batch.completed)?batch.completed.length:number(batch.completed??batch.completed_games,0),results=batch.results||{},metrics=batch.metrics||{},status=batch.status||'queued',active=!['completed','cancelled','canceled','failed'].includes(status);
    const a=batch.profiles?.[0]?.name||'First AI',b=batch.profiles?.[1]?.name||'Second AI',ci=metrics.score_ci95;
    const metricText=metrics.scored_pairs?`${count(metrics.scored_pairs)} scored pairs · ${a} score ${(number(metrics.a_pair_score)*100).toFixed(1)}% · 95% interval ${ci?.map(v=>(v*100).toFixed(0)+'%').join('–')||'—'}`:'No complete scored pairs yet.';
    return `<article class="batch-item"><strong>${batch.learning?'Learning batch':'Frozen benchmark'} <span class="history-status">${esc(status)}</span></strong><small>${count(completed)} / ${count(total)} games · ${esc(batch.config?.n?'N = '+batch.config.n:'')} · ${count(batch.nodes)} nodes/move</small><small>Seed ${esc(batch.seed??1)} · ${esc(batch.seed_set||'shared paired openings')}</small><progress max="${total}" value="${completed}"></progress><small>${esc(a)} ${count(results.a_wins??results.white_wins)} · ${esc(b)} ${count(results.b_wins??results.black_wins)} · ${count(results.draws)} draws · ${count(results.cutoffs)} cutoffs</small><small>${esc(metricText)}</small><small>${count(metrics.average_plies)} avg plies · ${(number(metrics.cutoff_rate)*100).toFixed(0)}% cutoff · ${number(metrics.compute_seconds).toFixed(1)}s compute</small>${batch.error?`<small>${esc(batch.error)}</small>`:''}${active?`<div class="control-row"><button class="button secondary" data-batch="${esc(batch.id)}" data-action="${status==='paused'?'resume':'pause'}">${status==='paused'?'Resume':'Pause'}</button><button class="button secondary" data-batch="${esc(batch.id)}" data-action="cancel">Cancel</button></div>`:''}</article>`;
  }).join('');
}
async function refreshHistory(more=false){const offset=more?state.history.length:0,result=await api(`/games?limit=100&offset=${offset}`);state.history=more?[...state.history,...(result.games||[])]:result.games||[];$('load-more-history').hidden=(result.games||[]).length<100;renderHistory();}
function renderHistory(){const list=$('history-list');list.innerHTML=state.history.length?state.history.map(game=>{const size=game.position?.size||(game.config?.n||1)*8,ply=game.position?.ply??game.ply??game.move_count??0;let date='';try{date=new Date(game.updated_at||game.created_at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}catch{}return `<button class="history-item" data-game="${esc(game.id)}"><span class="history-status">${esc(String(game.status||'playing').replaceAll('_',' '))}</span><strong>${size} × ${size} · ${game.config?.setup==='rows'?'Repeated rows':'Block expansion'}</strong><small>${Math.ceil(ply/2)} moves · ${esc(date)}${game.batch_id?' · batch game':''}</small></button>`;}).join(''):'<div class="empty-state"><span>♔</span>Your saved games will live here.</div>';}

const pointers=new Map();let gesture=null,pinchDistance=0,pinchActive=false;
$('occupied-square-colors').addEventListener('change',updateOccupiedSquareColors);
function localPoint(event){const rect=canvas.getBoundingClientRect();return {x:event.clientX-rect.left,y:event.clientY-rect.top};}
canvas.addEventListener('pointerdown',event=>{if(event.button!==0)return;canvas.focus({preventScroll:true});const p=localPoint(event);pointers.set(event.pointerId,p);canvas.setPointerCapture(event.pointerId);if(pointers.size===1){gesture={...p,startX:camera.x,startY:camera.y,dragged:false};pinchActive=false;}else if(pointers.size===2){pinchActive=true;const [a,b]=[...pointers.values()];pinchDistance=Math.hypot(a.x-b.x,a.y-b.y);if(gesture)gesture.dragged=true;}});
canvas.addEventListener('pointermove',event=>{if(!pointers.has(event.pointerId))return;const p=localPoint(event);pointers.set(event.pointerId,p);if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(pinchDistance>0)zoomAt(distance/pinchDistance,(a.x+b.x)/2,(a.y+b.y)/2);pinchDistance=distance;return;}if(!gesture||pinchActive)return;const dx=p.x-gesture.x,dy=p.y-gesture.y;if(Math.hypot(dx,dy)>5)gesture.dragged=true;if(gesture.dragged){camera.x=gesture.startX+dx;camera.y=gesture.startY+dy;camera.fitted=false;canvas.classList.add('dragging');$('follow-moves').checked=false;requestRender();}});
canvas.addEventListener('pointerup',event=>{const p=localPoint(event),click=pointers.size===1&&!pinchActive&&gesture&&!gesture.dragged;pointers.delete(event.pointerId);if(!pointers.size){gesture=null;canvas.classList.remove('dragging');}if(click)safely(()=>selectSquare(squareAt(p.x,p.y)));});
canvas.addEventListener('pointercancel',event=>{pointers.delete(event.pointerId);gesture=null;canvas.classList.remove('dragging');});
canvas.addEventListener('wheel',event=>{event.preventDefault();const p=localPoint(event);zoomAt(Math.exp(-Math.max(-300,Math.min(300,event.deltaY))*.002),p.x,p.y);},{passive:false});
mini.addEventListener('pointerdown',event=>{event.preventDefault();const pos=currentPosition();if(!pos)return;const rect=mini.getBoundingClientRect(),col=(event.clientX-rect.left)/rect.width*pos.size,row=(event.clientY-rect.top)/rect.height*pos.size;camera.x=camera.width/2-col*camera.cell;camera.y=camera.height/2-row*camera.cell;camera.fitted=false;$('follow-moves').checked=false;requestRender();});
canvas.addEventListener('keydown',event=>{const pos=currentPosition();if(!pos)return;const n=pos.size,sign=camera.flipped?-1:1;let focus=state.focus??state.selected??kingSquare(pos.turn)??0,row=Math.floor(focus/n),col=focus%n;if(event.key.startsWith('Arrow')){event.preventDefault();if(event.key==='ArrowLeft')col-=sign;if(event.key==='ArrowRight')col+=sign;if(event.key==='ArrowUp')row-=sign;if(event.key==='ArrowDown')row+=sign;state.focus=Math.max(0,Math.min(n-1,row))*n+Math.max(0,Math.min(n-1,col));const p=boardPoint(state.focus);if(p.x<0||p.y<0||p.x+camera.cell>camera.width||p.y+camera.cell>camera.height)focusSquare(state.focus,Math.max(camera.cell,24));$('board-description').textContent=`${squareName(state.focus)}${pos.board[state.focus]?' · '+colorName(Math.sign(pos.board[state.focus]))+' '+pieceNames[Math.abs(pos.board[state.focus])]:' · empty'}`;announce($('board-description').textContent);requestRender();}else if(event.key==='Enter'||event.key===' '){event.preventDefault();safely(()=>selectSquare(focus));}else if(event.key==='Escape'){state.selected=null;state.legal=[];state.legalRequest++;requestRender();}else if(event.key==='+'||event.key==='='){event.preventDefault();zoomAt(1.3);}else if(event.key==='-'){event.preventDefault();zoomAt(1/1.3);}else if(event.key==='Home'){event.preventDefault();fitBoard();}});

for(const button of document.querySelectorAll('[data-tab]'))button.addEventListener('click',()=>activateTab(button.dataset.tab));
for(const id of ['new-game-button','empty-new-game','edit-setup'])$(id).addEventListener('click',openSetup);
$('close-setup').addEventListener('click',()=>$('new-game-dialog').close());
$('new-game-form').addEventListener('submit',event=>{event.preventDefault();safely(createGame);});
$('setup-n').addEventListener('change',()=>{updateRangeOptions();safely(updatePreview);});
for(const id of ['setup-king','setup-range','setup-draw'])$(id).addEventListener('change',()=>safely(updatePreview));
for(const radio of document.querySelectorAll('input[name="setup"]'))radio.addEventListener('change',()=>safely(updatePreview));
for(const id of ['setup-white','setup-black','setup-white-time','setup-black-time'])$(id).addEventListener('change',updateSetupMode);
$('zoom-in').addEventListener('click',()=>zoomAt(1.4));$('zoom-out').addEventListener('click',()=>zoomAt(1/1.4));$('fit-board').addEventListener('click',fitBoard);$('play-view').addEventListener('click',playView);$('flip-board').addEventListener('click',()=>{const pos=currentPosition();if(!pos)return;camera.flipped=!camera.flipped;renderBoardStatistics();if(camera.fitted)fitBoard();else focusSquare(state.selected??state.focus??kingSquare(pos.turn),camera.cell);requestRender();});$('focus-last').addEventListener('click',()=>focusSquare(state.moves.at(-1)?.move?.to??kingSquare(),Math.max(camera.cell,32)));$('find-king').addEventListener('click',()=>focusSquare(kingSquare(),40));$('guides').addEventListener('change',requestRender);
$('dismiss-error').addEventListener('click',clearError);$('pause-game').addEventListener('click',()=>safely(()=>controlGame(state.game?.paused?'resume':'pause')));$('step-game').addEventListener('click',()=>safely(()=>controlGame('step')));$('move-now').addEventListener('click',()=>safely(()=>controlGame('move_now')));$('resign-game').addEventListener('click',()=>safely(()=>controlGame('resign')));$('draw-game').addEventListener('click',()=>safely(()=>controlGame('draw')));$('view-delay').addEventListener('change',()=>safely(()=>controlGame('set_delay',{value:number($('view-delay').value,.5)})));
$('evaluation-panel').addEventListener('toggle',()=>{if($('evaluation-panel').open)safely(refreshEvaluation);});
$('move-list').addEventListener('click',event=>{const button=event.target.closest('[data-replay]');if(button)setReplay(number(button.dataset.replay));});$('replay-start').addEventListener('click',()=>setReplay(0));$('replay-prev').addEventListener('click',()=>setReplay((state.replay??state.moves.length)-1));$('replay-next').addEventListener('click',()=>setReplay((state.replay??state.moves.length)+1));$('replay-live').addEventListener('click',()=>setReplay(null));
$('game-timeline-slider').addEventListener('input',()=>setReplay(number($('game-timeline-slider').value)));
$('timeline-play').addEventListener('click',()=>{if(replayPlayback.playing)replayPlayback.stop();else replayPlayback.start();});
$('timeline-live').addEventListener('click',()=>setReplay(null));
$('profile-select').addEventListener('change',fillProfileEditor);$('profile-form').addEventListener('submit',event=>{event.preventDefault();safely(()=>saveProfile(false));});$('clone-profile').addEventListener('click',()=>safely(()=>saveProfile(true)));$('reset-profile').addEventListener('click',()=>safely(resetProfile));
$('profile-versions-panel').addEventListener('toggle',()=>{if($('profile-versions-panel').open)safely(refreshProfileVersions);});$('profile-versions-list').addEventListener('click',event=>{const button=event.target.closest('[data-version]');if(button){const profile=state.profileVersions?.find(p=>p.version===number(button.dataset.version));if(profile)fillProfileEditor(profile);}});
$('batch-form').addEventListener('submit',event=>{event.preventDefault();safely(()=>startBatch(false));});$('pilot-batch').addEventListener('click',()=>safely(()=>startBatch(true)));$('refresh-batches').addEventListener('click',()=>safely(refreshBatches));$('batch-list').addEventListener('click',event=>{const button=event.target.closest('[data-batch]');if(button)safely(async()=>{await api(`/batches/${button.dataset.batch}/control`,'POST',{action:button.dataset.action});await refreshBatches();});});
$('refresh-history').addEventListener('click',()=>safely(refreshHistory));$('history-list').addEventListener('click',event=>{const button=event.target.closest('[data-game]');if(button)safely(()=>loadGame(button.dataset.game));});$('backup-data').addEventListener('click',()=>safely(async()=>{const result=await api('/backup','POST',{});$('backup-feedback').textContent='Backup saved: '+(result.path||result.filename||'complete');}));
$('load-more-history').addEventListener('click',()=>safely(()=>refreshHistory(true)));

async function init(){createPieceImages();resizeObserver=new ResizeObserver(resize);resizeObserver.observe($('board-viewport'));updateRangeOptions();const result=await api('/bootstrap');state.profiles=result.profiles||[];state.history=result.games||[];state.batches=result.batches||[];populateProfiles();renderHistory();renderBatches();await updatePreview();const existing=state.history.find(g=>g.status==='playing'&&!g.batch_id)||state.history.find(g=>!g.batch_id);if(existing)await loadGame(existing.id);else await createGame();$('connection-status').textContent='Saved on your machine';setInterval(()=>pollGame(),500);setInterval(renderSearchClock,200);setInterval(()=>{if(!$('tab-training').hidden&&Date.now()-lastBatchRefresh>4000)safely(refreshBatches);},1500);}
safely(init);
